begin;
select plan(10);
create temp table logo_fixture(actor uuid, outsider uuid, agency uuid, path text);
insert into logo_fixture values(gen_random_uuid(),gen_random_uuid(),null,null);
insert into auth.users(id,email) select actor,actor::text || '@example.invalid' from logo_fixture union all select outsider,outsider::text || '@example.invalid' from logo_fixture;
select set_config('request.jwt.claim.sub',(select actor::text from logo_fixture),true);
update logo_fixture set agency=public.onboard_agency('Logo Fixture',actor::text,'fixture@example.invalid','NG','Africa/Lagos','Logo Tester');
update logo_fixture set path=agency::text || '/' || gen_random_uuid()::text || '.png';
insert into storage.objects(bucket_id,name) select 'agency-logos',path from logo_fixture;
select ok(not has_function_privilege('anon','public.update_agency_logo(uuid,text,text,text)','EXECUTE'),'anonymous execution denied');
select lives_ok($$select public.update_agency_logo(agency,path,null,'logo-test') from logo_fixture$$,'owner can set uploaded logo');
select is((select logo_path from public.agencies where id=(select agency from logo_fixture)),(select path from logo_fixture),'logo path persisted');
select is((select count(*) from public.activity_events where agency_id=(select agency from logo_fixture) and event_type='agency.logo_updated'),1::bigint,'branding change audited');
select throws_ok($$select public.update_agency_logo(agency,null,null,'stale-test') from logo_fixture$$,'40001','Logo changed; refresh and try again','stale editor cannot remove a newer logo');
select throws_ok($$select public.update_agency_logo(agency,outsider::text || '/' || gen_random_uuid()::text || '.png',path,'tenant-test') from logo_fixture$$,'22023','Invalid agency logo','cross-tenant logo path denied');
select set_config('request.jwt.claim.sub',(select outsider::text from logo_fixture),true);
select throws_ok($$select public.update_agency_logo(agency,null,path,'outsider-test') from logo_fixture$$,'42501','Logo access denied','nonmember denied');
select set_config('request.jwt.claim.sub',(select actor::text from logo_fixture),true);
update public.agency_memberships set role='recruiter' where agency_id=(select agency from logo_fixture);
select throws_ok($$select public.update_agency_logo(agency,null,path,'role-test') from logo_fixture$$,'42501','Logo access denied','recruiter denied');
update public.agency_memberships set role='administrator' where agency_id=(select agency from logo_fixture);
select lives_ok($$select public.update_agency_logo(agency,null,path,'remove-test') from logo_fixture$$,'administrator can remove logo');
update public.agency_memberships set status='revoked' where agency_id=(select agency from logo_fixture);
select throws_ok($$select public.update_agency_logo(agency,null,null,'revoked-test') from logo_fixture$$,'42501','Logo access denied','revoked administrator denied');
select * from finish();
rollback;
